package com.shazwan.idash;
import android.app.*;import android.content.*;import android.os.*;import java.io.*;import java.util.*;import org.json.*;
/** Two separate instrumentation processes, with shell force-stop between write/read. Disposable emulator only. */
public class AppearancePersistenceChecks extends Instrumentation {
 String stage;LauncherActivity a;SharedPreferences prefs;int count;JSONObject backup;boolean keep;
 void check(boolean good,String why){if(!good)throw new AssertionError(why);count++;}
 void ui(Runnable r){Throwable[] e={null};runOnMainSync(()->{try{r.run();}catch(Throwable t){e[0]=t;}});waitForIdleSync();if(e[0]!=null)throw new AssertionError(e[0]);}
 File backupFile(){return new File(getTargetContext().getFilesDir(),"appearance-test-backup.json");}
 JSONObject snapshot()throws Exception{JSONObject out=new JSONObject();for(Map.Entry<String,?> entry:prefs.getAll().entrySet()){Object v=entry.getValue();JSONObject item=new JSONObject();item.put("type",v instanceof Boolean?"bool":v instanceof Integer?"int":v instanceof Long?"long":v instanceof Float?"float":v instanceof Set?"set":"string");item.put("value",v instanceof Set?new JSONArray((Set<?>)v):v);out.put(entry.getKey(),item);}return out;}
 void restore()throws Exception{if(backup==null)return;SharedPreferences.Editor edit=prefs.edit().clear();Iterator<String> keys=backup.keys();while(keys.hasNext()){String key=keys.next();JSONObject value=backup.getJSONObject(key);switch(value.getString("type")){case "bool":edit.putBoolean(key,value.getBoolean("value"));break;case "int":edit.putInt(key,value.getInt("value"));break;case "long":edit.putLong(key,value.getLong("value"));break;case "float":edit.putFloat(key,(float)value.getDouble("value"));break;case "set":Set<String> values=new HashSet<>();JSONArray array=value.getJSONArray("value");for(int i=0;i<array.length();i++)values.add(array.getString(i));edit.putStringSet(key,values);break;default:edit.putString(key,value.getString("value"));}}edit.commit();backupFile().delete();}
 public void onCreate(Bundle b){super.onCreate(b);stage=b==null?"read":b.getString("stage","read");start();}
 public void onStart(){Bundle result=new Bundle();int code=Activity.RESULT_CANCELED;try{
  prefs=getTargetContext().getSharedPreferences("idash",0);
  if("write".equals(stage)){backup=snapshot();JSONObject record=new JSONObject().put("prefs",backup).put("pid",android.os.Process.myPid());try(OutputStream out=new FileOutputStream(backupFile())){out.write(record.toString().getBytes("UTF-8"));}}
  else{StringBuilder raw=new StringBuilder();try(BufferedReader in=new BufferedReader(new InputStreamReader(new FileInputStream(backupFile()),"UTF-8"))){String line;while((line=in.readLine())!=null)raw.append(line);}JSONObject record=new JSONObject(raw.toString());backup=record.getJSONObject("prefs");check(record.getInt("pid")!=android.os.Process.myPid(),"read occurs in a genuinely new process");}
  a=(LauncherActivity)startActivitySync(new Intent(getTargetContext(),LauncherActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));ui(()->new DashSettings(a).open("Appearance"));long until=SystemClock.elapsedRealtime()+30000;while(!a.appearanceEditor.cacheReady&&SystemClock.elapsedRealtime()<until)Thread.sleep(100);check(a.appearanceEditor.cacheReady,"editor ready");
  if("write".equals(stage)){ui(()->{AppearanceEditor e=a.appearanceEditor;e.change(0,2);e.change(1,27);e.change(2,0);e.change(3,4);e.change(4,2);e.change(5,0);});until=SystemClock.elapsedRealtime()+30000;while(!a.appearanceEditor.cacheReady&&SystemClock.elapsedRealtime()<until)Thread.sleep(100);check(a.appearanceEditor.cacheReady,"LOW cache prepared before Apply");ui(()->a.appearanceEditor.applyButton.performClick());check(GlassAppearance.read(a).quality==0&&GlassAppearance.read(a).transparency==27,"Apply stores requested values");Thread.sleep(800);keep=true;}
  else{GlassAppearance s=GlassAppearance.read(a);check(s.customized&&s.tone==2&&s.transparency==27&&s.quality==0&&s.tint==4&&s.reflection==2&&!s.motion,"all settings survive force-stop/relaunch");check(a.appearanceEditor.saved.same(s),"editor displays persisted values");check(IosStyle.quality(a)==0,"global renderer reads persisted LOW");check(a.appearanceEditor.cache.frame.bitmap==null||Math.max(a.appearanceEditor.cache.frame.bitmap.getWidth(),a.appearanceEditor.cache.frame.bitmap.getHeight())<=128,"persisted LOW cache bound");}
  result.putString("stream","PASS: "+count+" appearance process-persistence "+stage+" checks\n");code=Activity.RESULT_OK;
 }catch(Throwable e){result.putString("stream","FAIL after "+count+": "+e+"\n");}finally{try{if(!keep)restore();}catch(Exception failure){result.putString("stream","FAIL restoring test profile: "+failure);code=Activity.RESULT_CANCELED;}if(a!=null)ui(()->{if(a.appearanceEditor!=null)a.appearanceEditor.close();a.finish();});}finish(code,result);}
}
